// Les 3 fichiers lus juste avant : les règles métier et les deux prompts.
// Ils sont relus à chaque email : modifier un prompt ou une règle ne demande
// aucune modification du workflow.
const files = {};
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  files[items[i].binary.data.fileName] = buffer.toString('utf8');
}

const rules = JSON.parse(files['business_rules.json']);

// Les listes de valeurs du prompt viennent de la configuration (source unique).
let classify = files['classify_extract.md'];
for (const key of ['categories', 'priorities', 'primary_intent_order']) {
  classify = classify.replaceAll(`{{${key}}}`, rules[key].map(v => '`' + v + '`').join(', '));
}

return [{ json: { rules, prompts: { classify, draft: files['draft_response.md'] } } }];

// Met l'email reçu au format de travail : texte brut, date de réception,
// et message prêt à envoyer au modèle (avec un calendrier des 14 jours suivants).
const body = $('Webhook').first().json.body;
for (const field of ['message_id', 'received_at', 'sender', 'subject', 'body']) {
  if (!body[field]) throw new Error(`Champ obligatoire manquant dans la requête : ${field}`);
}
const received = DateTime.fromISO(body.received_at, { setZone: true });
if (!received.isValid) throw new Error(`received_at invalide : ${body.received_at}`);

const WEEKDAYS = ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'];
const MONTHS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août',
                'septembre', 'octobre', 'novembre', 'décembre'];

const bodyText = body.body
  .replace(/<br\s*\/?>|<\/div>|<\/p>/gi, '\n')       // fins de ligne HTML
  .replace(/<[^>]+>/g, '')                           // autres balises HTML
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/^--\s*\n(envoyé depuis|sent from).*$/gim, '') // signature d'envoi mobile
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n\s*\n+/g, '\n\n')
  .trim();

// Le modèle lit la date dans ce calendrier au lieu de la calculer.
const calendar = [];
for (let offset = 0; offset <= 14; offset++) {
  const day = received.startOf('day').plus({ days: offset });
  const label = offset === 0 ? " (aujourd'hui)" : offset === 1 ? ' (demain)' : '';
  calendar.push(`- ${WEEKDAYS[day.weekday - 1]} ${day.day} ${MONTHS[day.month - 1]} = ${day.toISODate()}${label}`);
}

const userMessage =
  `Date de réception : ${body.received_at} (${WEEKDAYS[received.weekday - 1]})\n` +
  `Calendrier des jours suivants :\n${calendar.join('\n')}\n` +
  `Expéditeur : ${body.sender}\n` +
  `Objet : ${body.subject}\n` +
  `Message :\n${bodyText}`;

return [{ json: {
  message_id: body.message_id,
  received_at: body.received_at,
  sender: body.sender,
  subject: body.subject,
  body_text: bodyText,
  attachments: (body.attachments || []).map(a => ({ filename: a.filename, mime_type: a.mime_type })),
  test_run: body.test_run || '',
  user_message: userMessage,
} }];

// Écarte, avant tout appel au LLM, les réponses automatiques et les erreurs de distribution.
// Les règles sont dans config/business_rules.json (clé filtering).
const email = $json;
const rules = $('Charger la configuration').first().json.rules.filtering;
const subject = email.subject.trim().toLowerCase();
const localPart = email.sender.split('@')[0].toLowerCase();

const prefix = rules.subject_prefixes.find(p => subject.startsWith(p));
const daemon = rules.sender_local_parts.includes(localPart);

const reason = prefix ? `Réponse automatique (objet commençant par « ${prefix} »)`
  : daemon ? `Erreur de distribution (expéditeur ${localPart})` : '';

return [{ json: { ...email, filtered: Boolean(reason), filter_reason: reason } }];

// Construit la requête envoyée au modèle principal (Groq) et celle du secours (Gemini).
// Si l'item vient de « Relancer ? », on ajoute l'erreur de la réponse précédente.
const config = $('Charger la configuration').first().json;
const email = $('Filtrer').first().json;
const attempt = $json.retry_error ? $json.attempt + 1 : 1;

const messages = [
  { role: 'system', content: config.prompts.classify },
  { role: 'user', content: email.user_message },
];
if ($json.retry_error) {
  messages.push({ role: 'user', content:
    `Ta réponse précédente était invalide : ${$json.retry_error}. ` +
    `Réponds uniquement par l'objet JSON demandé, avec les valeurs autorisées.` });
}

// JSON simple (json_object) et non strict : en mode json_schema, Groq tronque les
// textes longs de ce modèle (voir eval/model-selection.md). Le code valide le format.
const base = { temperature: 0, max_completion_tokens: 1500, response_format: { type: 'json_object' }, messages };
return [{ json: {
  attempt,
  request: { ...base, model: $env.LLM_PRIMARY_MODEL, reasoning_effort: 'none' },
  fallback_request: { ...base, model: $env.LLM_FALLBACK_MODEL },
} }];

// Lit la réponse du modèle (Groq ou Gemini) et vérifie qu'elle respecte le format attendu.
// Le LLM extrait ; ici, le code contrôle.
const rules = $('Charger la configuration').first().json.rules;
const prepared = $('Préparer la classification').first().json;   // dernier passage
const email = $('Filtrer').first().json;
const response = $json;
const content = response.choices?.[0]?.message?.content || '';

const REQUIRED = ['category', 'priority', 'customer_name', 'company', 'email', 'phone',
                  'requested_date', 'secondary_requests', 'summary', 'ambiguous'];
let q = null;
let error = '';
// Item venu de la sortie d'erreur du secours : Groq et Gemini sont tous deux en panne.
const providerDown = Boolean(response.error);
if (providerDown) {
  // Le message d'erreur brut des API contient souvent du JSON : on n'en garde que la phrase utile.
  const raw = String(response.error.description || response.error.message || '');
  const short = (raw.match(/\\?"message\\?":\s*\\?"([^"\\]+)/) || [])[1] || raw;
  error = `LLM indisponible (Groq et Gemini) : ${short.slice(0, 200)}`;
} else {
  try {
    q = JSON.parse(content.trim().replace(/^```(?:json)?\s*|\s*```$/g, ''));
  } catch (e) {
    error = `JSON invalide (${e.message})`;
  }
}
if (q) {
  const missing = REQUIRED.filter(key => !(key in q));
  if (missing.length) error = `champs manquants : ${missing.join(', ')}`;
  else if (!rules.categories.includes(q.category)) error = `catégorie non autorisée : ${q.category}`;
  else if (!rules.priorities.includes(q.priority)) error = `priorité non autorisée : ${q.priority}`;
  else if (!Array.isArray(q.secondary_requests)) error = 'secondary_requests doit être une liste';
  else if (typeof q.summary !== 'string' || !q.summary.trim()) error = 'résumé vide';
  else if (q.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(q.email)) error = `email invalide : ${q.email}`;
  else if (q.requested_date) {
    const requested = DateTime.fromISO(q.requested_date);
    const received = DateTime.fromISO(email.received_at, { setZone: true });
    if (!requested.isValid) error = `date invalide : ${q.requested_date}`;
    else if (requested < received.startOf('day')) error = `date passée : ${q.requested_date}`;
  }
}

return [{ json: {
  valid: !error,
  provider_down: providerDown,
  retry_error: error,
  attempt: prepared.attempt,
  model: response.model || '',
  qualification: error ? null : q,
  usage: response.usage || {},
} }];

// Toutes les décisions sont prises ici, par des règles écrites (config/business_rules.json) :
// rattachement, priorité, revue humaine, équipe, échéance de réponse.
const rules = $('Charger la configuration').first().json.rules;
const email = $('Filtrer').first().json;
const result = $('Lire la qualification').first().json;   // dernier passage, après relance éventuelle
const received = DateTime.fromISO(email.received_at, { setZone: true });
const reasons = [];

let q = result.qualification;
if (result.provider_down) {
  reasons.push(result.retry_error);   // la demande est gardée, statut ERROR, traitée à la main
} else if (!result.valid) {
  reasons.push(`Sortie du modèle inexploitable après ${result.attempt} essai(s) : ${result.retry_error}`);
}
if (!result.valid) {
  // Pas de qualification : on garde au moins l'expéditeur et l'objet pour que l'agent sache qui a écrit.
  q = { category: 'AUTRE', priority: 'NORMAL', customer_name: null, company: null, email: email.sender, phone: null,
        requested_date: null, secondary_requests: [], summary: `Non qualifié. Objet : ${email.subject}`, ambiguous: false };
}

const ORDER = rules.priorities;   // du plus urgent au moins urgent
const raise = (current, minimum) => (ORDER.indexOf(current) > ORDER.indexOf(minimum) ? minimum : current);
let priority = q.priority;

// 1. Rattachement : un ticket encore ouvert du même client (même email ou même téléphone)
const digits = value => String(value || '').replace(/\D/g, '');
const since = received.minus({ days: rules.linking.window_days });
const related = $input.all()
  .map(item => item.json)
  .filter(t => t.ticket_id && !rules.linking.closed_statuses.includes(t.status))
  .filter(t => String(t.test_run || '') === email.test_run)      // les tests ne se mélangent pas
  .filter(t => DateTime.fromISO(String(t.received_at), { setZone: true }) >= since)
  .filter(t => (q.email && t.email && String(t.email).toLowerCase() === q.email.toLowerCase())
            || (q.phone && digits(t.phone) && digits(t.phone) === digits(q.phone)))
  .sort((a, b) => (String(a.received_at) < String(b.received_at) ? 1 : -1))[0];
if (related) priority = raise(priority, 'HIGH');                 // un client qui relance

// 2. Échéance proche : filet de sécurité sur le calcul de dates du modèle
const escalation = rules.deadline_escalation;
if (q.requested_date) {
  const requested = DateTime.fromISO(q.requested_date, { zone: received.zone });
  if (requested.diff(received, 'hours').hours < escalation.within_hours) {
    priority = raise(priority, escalation.min_priority);
  }
}

// 3. Revue humaine obligatoire (seulement si la qualification est valide : sinon la raison est déjà connue)
const review = rules.manual_review;
if (result.valid) {
  if (review.categories.includes(q.category)) {
    reasons.push(q.category === 'RECLAMATION' ? 'Réclamation : réponse à rédiger par un humain' : 'Demande non reconnue');
  }
  if (review.priorities.includes(priority)) reasons.push('Urgence : traitement immédiat par un humain');
  if (review.if_ambiguous && q.ambiguous) reasons.push('Intention principale impossible à déterminer');
  if (review.if_no_contact && !q.email && !q.phone) reasons.push('Aucun moyen de recontacter le client');
}

// 4. Routage et échéance de réponse
return [{ json: {
  qualification: { ...q, priority },
  team: rules.team_by_category[q.category],
  due_at: received.plus({ hours: rules.response_delay_hours[priority] }).toISO(),
  related_ticket_id: related ? related.ticket_id : '',
  status: result.provider_down ? 'ERROR' : reasons.length ? 'NEEDS_MANUAL_REVIEW' : 'PENDING_REVIEW',
  review_reason: reasons.join(' ; '),
  model: result.model,
} }];

// Le brouillon ne s'appuie que sur la FAQ : les entrées de la catégorie principale,
// plus toujours les questions générales (pour répondre aux demandes secondaires).
const config = $('Charger la configuration').first().json;
const email = $('Filtrer').first().json;
const q = $('Appliquer les règles métier').first().json.qualification;

const entries = $input.all().map(item => item.json)
  .filter(e => e.id && [q.category, 'INFORMATION'].includes(e.category));
const faqBlock = entries.map(e => `[${e.id}] ${e.question} — ${e.answer}`).join('\n');
const secondary = q.secondary_requests.length ? q.secondary_requests.join(' ; ') : 'aucune';

const user =
  `Email du client :\nObjet : ${email.subject}\n${email.body_text}\n\n` +
  `Qualification : catégorie ${q.category} ; nom : ${q.customer_name || 'inconnu'} ; ` +
  `demandes secondaires : ${secondary}\n\n` +
  `Entrées de FAQ fournies :\n${faqBlock}\n\n` +
  `Rappel : rédige le brouillon dans la langue de l'email du client, même si la FAQ est en français.`;

const base = { temperature: 0, max_completion_tokens: 1500, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: config.prompts.draft }, { role: 'user', content: user }] };
return [{ json: {
  entries,
  request: { ...base, model: $env.LLM_PRIMARY_MODEL, reasoning_effort: 'none' },
  fallback_request: { ...base, model: $env.LLM_FALLBACK_MODEL },
} }];

// Trois contrôles déterministes, avant de proposer le brouillon à un agent :
// citations de FAQ existantes, aucun nombre inventé, signature présente.
const prepared = $('Préparer le brouillon').first().json;
const q = $('Appliquer les règles métier').first().json.qualification;
const email = $('Filtrer').first().json;
const content = $json.choices?.[0]?.message?.content || '';

let draft = null;
let problem = '';
if ($json.error) {
  const raw = String($json.error.description || $json.error.message || '');
  const short = (raw.match(/\\?"message\\?":\s*\\?"([^"\\]+)/) || [])[1] || raw;
  problem = `LLM indisponible pour le brouillon (Groq et Gemini) : ${short.slice(0, 200)}`;
} else {
  try {
    draft = JSON.parse(content.trim().replace(/^```(?:json)?\s*|\s*```$/g, ''));
  } catch (e) {
    problem = 'brouillon illisible (JSON invalide)';
  }
}
if (draft && (typeof draft.draft !== 'string' || !draft.draft.trim())) problem = 'brouillon vide';

const checks = [];
if (draft && !problem) {
  const cited = Array.isArray(draft.faq_ids_used) ? draft.faq_ids_used : [];
  const provided = new Set(prepared.entries.map(e => e.id));
  const invalid = cited.filter(id => !provided.has(id));
  if (invalid.length) checks.push(`citations inexistantes : ${invalid.join(', ')}`);

  // Chaque nombre du brouillon doit exister dans l'email, la qualification ou les entrées citées.
  const used = prepared.entries.filter(e => cited.includes(e.id));
  const sources = [email.subject, email.body_text, JSON.stringify(q), ...used.map(e => `${e.question} ${e.answer}`)].join(' ');
  const known = new Set(sources.match(/\d+/g) || []);
  const unsupported = [...new Set(draft.draft.match(/\d+/g) || [])].filter(n => !known.has(n));
  if (unsupported.length) checks.push(`nombres non sourcés : ${unsupported.join(', ')}`);

  if (!/(Le service client|Customer Service)\s*$/.test(draft.draft.trim())) {
    checks.push('signature absente (texte peut-être tronqué)');
  }
}

return [{ json: {
  draft_response: draft?.draft || '',
  draft_faq_ids: (draft?.faq_ids_used || []).join(', '),
  draft_unanswered: (draft?.unanswered || []).join(' | '),
  draft_model: $json.model || '',
  draft_check: problem || checks.join(' ; '),
} }];

// Assemble la ligne de l'onglet tickets, quel que soit le chemin suivi
// (email filtré, revue obligatoire, ou brouillon proposé).
const email = $('Filtrer').first().json;
const base = {
  ticket_id: `T-${$execution.id}`,
  message_id: email.message_id,
  received_at: email.received_at,
  processed_at: $now.toISO(),
  execution_id: $execution.id,
  test_run: email.test_run,
};
if (email.filtered) {
  return [{ json: { ...base, status: 'FILTERED', review_reason: email.filter_reason } }];
}

const decision = $('Appliquer les règles métier').first().json;
const q = decision.qualification;
let status = decision.status;
let reason = decision.review_reason;
let draft = {};
if ($('Contrôler le brouillon').isExecuted) {
  draft = $('Contrôler le brouillon').first().json;
  if (draft.draft_check) {
    status = 'NEEDS_MANUAL_REVIEW';
    reason = `Brouillon rejeté par les contrôles : ${draft.draft_check}`;
  }
}

return [{ json: {
  ...base,
  related_ticket_id: decision.related_ticket_id,
  customer_name: q.customer_name ?? '',
  company: q.company ?? '',
  email: q.email ?? '',
  phone: q.phone ?? '',
  category: q.category,
  priority: q.priority,
  requested_date: q.requested_date ?? '',
  secondary_requests: (q.secondary_requests || []).join(' | '),
  summary: q.summary,
  ambiguous: q.ambiguous,
  team: decision.team,
  due_at: decision.due_at,
  status,
  review_reason: reason,
  draft_response: draft.draft_response || '',
  draft_faq_ids: draft.draft_faq_ids || '',
  draft_unanswered: draft.draft_unanswered || '',
  draft_outcome: '',
  model: [decision.model, draft.draft_model].filter(Boolean).join(' / '),
} }];
